use vstd::prelude::*;

verus! {
    /// Given an 8-bit signed integer n ≥ 2, returns
    /// - "black\n"    if n is odd,
    /// - "white\n1 2\n" if n is even.
    fn solve(n: i8) -> (result: String)
        requires
            n >= 2,
        ensures
            // If n is odd, we return exactly "black\n"
            (n % 2 != 0 && result == String::from("black\n"))
            // If n is even, we return exactly "white\n1 2\n"
            || (n % 2 == 0 && result == String::from("white\n1 2\n")),
    {
        if n % 2 != 0 {
            String::from("black\n")
        } else {
            String::from("white\n1 2\n")
        }
    }
}

